SELECT 
l.id as 'lead_id',
l.contactId as 'customer_id',
l.make as 'make',
l.model as 'model',
l.trim as 'trim',
l.transmission as 'transmission',
l.year as 'year',
l.mileage as 'mileage',
l.plate as 'plate',
l.userGoogleId as 'user_google_id',
l.price as 'price',
l.minPrice as 'min_price',
l.maxPrice as 'max_price',
l.leadSource as 'lead_source',
l.status as 'lead_status',
l.comment as 'lead_comment',
l.latestAppointment as 'latest_booking_id',
l.rejectionReasons as 'rejection_reasons', 
l.cancellationReason as 'cancellation_reason',
l.responsible as 'responsible',
l.responsibleName as 'responsible_name',
l.serviceType as 'service_type',
l.cancelledInStatus as 'cancelled_in_status',
l.ownerName as 'owner_name',
l.ownerPhone as 'owner_phone',
l.callStatus as 'call_status',
l.discardedReason as 'discarded_reason',
l.externalLeadId as 'external_lead_id',
l.referralCode as 'referral_code',
l.smsCode as 'sms_code',
UNIX_TIMESTAMP(l.createdAt) as 'lead_created_at',
l.createdByUser as 'lead_created_by_id',
l.createdByUserEmail as 'lead_created_by',
UNIX_TIMESTAMP(l.updatedAt) as 'lead_last_modified',
l.updatedByUser as 'lead_last_modified_by_id',
l.updatedByUserEmail as 'lead_last_modified_by',
UNIX_TIMESTAMP(l.deletedAt) as 'deleted_at',
l.deletedByUser as 'deleted_by_id',
l.deletedByUserEmail as 'deleted_by',
l.country as 'country_id',
l.utmSource as 'utm_source',
l.utmCampaign as 'utm_campaign',
l.utmMedium as 'utm_medium',
l.utmTerm as 'utm_term', 
l.utmContent as 'utm_content',
l.utmCampaignId as 'utm_campaign_id',
l.utmAdgroupId as 'utm_ad_group_id',
l.sellingUrgency as 'selling_urgency',
l.gclid as 'gclid',
l.VINnumber as 'vin',
l.lastOffer as 'last_offer_price',
l.sellerExpectationPrice as 'seller_expectation_price',
l.selfInspection as 'self_inspection',
l.inspectionType as 'inspection_type',
l.area as 'lead_area',
l.responsible as 'responsible_person',
l.responsibleName as 'responsible_person_name',
l.locale as 'lead_system_locale'
FROM fcgContact.carLeadCallback l
where l.updatedAt >= '{{params.start_ts}}' and l.updatedAt < '{{params.end_ts}}'